// Excerpt from StopEventRun(_txt_id, _pos): run three coroutines concurrently
// (moving the player, panning the camera, and showing a message) until all finish.
local hTenmaL = CMND_GET_CHARA_HANDLE(GET_HANDLE_TYPE_CTRL_PC, true);
local hCam = CMND_GET_ACT_CAMERA();
local TenmaProc = function () : (hTenmaL, _pos)
{
	WaitFrame(1);
	EvLowMdlSetLookAtPos(hTenmaL, _pos, 20);
};
local CameraProc = function () : (hCam, _pos)
{
	WaitCamCtrlMoving(hCam);
};
local TextProc = function () : (_txt_id)
{
	CreateSpeech(_txt_id);
};
InitChildThread(3);
AddChildThread(TenmaProc);
AddChildThread(CameraProc);
AddChildThread(TextProc);
RunChildThread();
